def cnt_block(r,c,ai,aj):
    # cell at corner (ai,aj) of 2x2 block
    rs=[r,r-1] if ai else [r,r+1]
    cs=[c,c-1] if aj else [c,c+1]
    n=0
    for rr in rs:
        for cc in cs:
            if 0<=rr<7 and 0<=cc<7 and inp[rr][cc]==8: n+=1
    return n
