def solve2(g):
    cellset={(r,c) for r in range(7) for c in range(7) if g[r][c]==8}
    pieces=[]
    for r in range(6):
        for c in range(6):
            blk=[(r+i,c+j) for i in(0,1) for j in(0,1)]
            inside=[p for p in blk if p in cellset]
            if len(inside)==4:
                pieces.append((frozenset(blk),1))
                for m in blk:
                    pieces.append((frozenset(p for p in blk if p!=m),
                        {(0,0):2,(0,1):4,(1,0):3,(1,1):5}[(m[0]-r,m[1]-c)]))
            elif len(inside)==3:
                miss=[p for p in blk if p not in inside][0]
                pieces.append((frozenset(inside),{(0,0):2,(0,1):4,(1,0):3,(1,1):5}[(miss[0]-r,miss[1]-c)]))
    sols=[]
    def bt(rem,acc):
        if not rem: sols.append(list(acc)); return
        p0=min(rem)
        for piece,col in pieces:
            if p0 in piece and piece<=rem:
                bt(rem-piece,acc+[(piece,col)])
    bt(frozenset(cellset),[])
    return sols
def render(g,s):
    o=[row[:] for row in g]
    for r in range(7):
        for c in range(7):
            if o[r][c]: o[r][c]=0
    for pc,col in s:
        for (r,c) in pc: o[r][c]=col
    return o
